head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common_etn.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.vScrenID = "ULDSTF08071.xml";
scwin.pMenuID = $c.cm.InfoMenuID();
scwin.fn_GetPar, scwin.fn_SetPar, scwin.fr_SecuGrpId;
scwin.flagVal;
scwin.TR_JOB;
scwin.ETN_MBR_INFO_TP_CD = "3";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetDataHeader = function() {
    dts_Item.removeAll();
    //dts_Item.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
    //껍데기만 만들고 사용자필드를 사용함
    dts_Item.insertRow();
};
scwin.fn_GetParIsur = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[2] = scwin.fr_SecuGrpId; // 명칭값을 포함할 컨트롤
    arrPar[3] = "9"; // 회사코드팝업 전체데이터
    return arrPar.length;
};
scwin.fn_SetParIsur = function(arrPar) {

};
scwin.fn_SetValue = function(row) {
    if (row > 0) {
        //그리드에서 선택시
        scwin.TR_JOB = "U";
        scwin.fn_Enable_Item();
        $c.stf.setObjectValue(txb_NotiTitle_5, dts_List_5.getCellData(eval(row), "NOTI_TITLE"));
        $c.stf.setObjectValue(txa_NotiContn_5, dts_List_5.getCellData(eval(row), "NOTI_CONTN"));
        $c.stf.setObjectValue(edt_SDate_5_1, $c.ut.replaceAll(dts_List_5.getCellData(eval(row), "STRT_DD"), "-", ""));
        $c.stf.setObjectValue(edt_SDate_5_2, $c.ut.replaceAll(dts_List_5.getCellData(eval(row), "END_DD"), "-", ""));
    }
};
scwin.fn_Enable_Item = function() {
    $c.stf.setObjectValue(txb_NotiTitle_5, "");
    $c.stf.setObjectValue(txa_NotiContn_5, "");
    $c.stf.setObjectValue(edt_SDate_5_1, "");
    $c.stf.setObjectValue(edt_SDate_5_2, "");
    btn_SDate_5_1.setDisabled(false);
    btn_SDate_5_2.setDisabled(false);
    edt_SDate_5_1.setReadOnly(false);
    edt_SDate_5_2.setReadOnly(false);
    txb_NotiTitle_5.setReadOnly(false);
    txa_NotiContn_5.setReadOnly(false);
    txb_NotiTitle_5.setStyle("backgroundcolor", "#ffffff");
    txa_NotiContn_5.style.background = "#ffffff";
    edt_SDate_5_1.setStyle("backgroundcolor", "#ffffff");
    edt_SDate_5_2.setStyle("backgroundcolor", "#ffffff");
};
scwin.fn_Disable_Item = function() {
    $c.stf.setObjectValue(txb_NotiTitle_5, "");
    $c.stf.setObjectValue(txa_NotiContn_5, "");
    $c.stf.setObjectValue(edt_SDate_5_1, "");
    $c.stf.setObjectValue(edt_SDate_5_2, "");
    btn_SDate_5_1.setDisabled(true);
    btn_SDate_5_2.setDisabled(true);
    edt_SDate_5_1.setReadOnly(true);
    edt_SDate_5_2.setReadOnly(true);
    txb_NotiTitle_5.setReadOnly(true);
    txa_NotiContn_5.setReadOnly(true);
    txb_NotiTitle_5.setStyle("backgroundcolor", "#b9d4f7");
    txa_NotiContn_5.style.background = "#b9d4f7";
    edt_SDate_5_1.setStyle("backgroundcolor", "#b9d4f7");
    edt_SDate_5_2.setStyle("backgroundcolor", "#b9d4f7");
};
scwin.fn_Enable_BtnSend = function(status) {
    if (status) {
        btn_Send_Mail.src = "../img/btn_send_mail.gif";
        btn_Send_Mail.setDisabled(false);
    } else {
        btn_Send_Mail.src = "../img/btn_send_mail_dis.gif";
        btn_Send_Mail.setDisabled(true);
    }
};
scwin.fn_list_sync = function() {
    scwin.fn_Disable_Item();
    var url = "/etn/EtnStatMgt.do?method=listEtnExchDeclInfo&inputMessageId=ETN_EXCH_DECL_INFO_INOUT";
    url += "&ETN_MBR_INFO_TP_CD=" + scwin.ETN_MBR_INFO_TP_CD;
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_List_5.DataID = encodeURI(url);
    dts_List_5.Reset();
    $c.cm.ShowWin(grd_List_5);
    /*
    url = "/etn/EtnStatMgt.do?method=listSendMailList";
    url += "&SCREN_ID=" + vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_MailList.DataID = encodeURI(url);
    dts_MailList.reset();
    */

};
scwin.fn_CheckForm = function() {
    if ($c.stf.getObjectValue(txb_NotiTitle_5) == "") {
        $c.win.alert("[제목]을 입력하세요.");
        txb_NotiTitle_5.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txa_NotiContn_5) == "") {
        $c.win.alert("[내용]을 입력하세요.");
        txa_NotiContn_5.focus();
        return false;
    }
    if (!$c.lce.checkDdTm("DD", edt_SDate_5_1, "메시지 표시기간 시작", true)) return false;
    if (!$c.lce.checkDdTm("DD", edt_SDate_5_2, "메시지 표시기간 종료", true)) return false;
    if (edt_SDate_5_1.getValue() == "") {
        $c.win.alert("[[메시지 표시기간 시작일]을 입력하세요.");
        edt_SDate_5_1.focus();
        return false;
    }
    if (edt_SDate_5_2.getValue() == "") {
        $c.win.alert("[[메시지 표시기간 종료일]을 입력하세요.");
        edt_SDate_5_2.focus();
        return false;
    }
    if (edt_SDate_5_2.getValue() != "" && (edt_SDate_5_1.getValue() > edt_SDate_5_2.getValue())) {
        $c.win.alert("[메시지 표시기간 종료일]은 [메시지 표시기간 시작일]이후로 입력하세요.");
        edt_SDate_5_2.focus();
        return false;
    }
    return true;
};
scwin.fn_trs = function() {
    //alert("INFO_RND : "+dts_List_5.NameString(dts_List_5.RowPosition, "INFO_RND"));
    var vScrenProcsTpCD = SCREN_PROCS_TP_CD_03;
    if (scwin.TR_JOB == "I") vScrenProcsTpCD = SCREN_PROCS_TP_CD_02;

    else if (scwin.TR_JOB == "U") vScrenProcsTpCD = SCREN_PROCS_TP_CD_03;

    else if (scwin.TR_JOB == "D") vScrenProcsTpCD = SCREN_PROCS_TP_CD_04;
    dts_Item.setCellData(1, "NOTI_TITLE", $c.stf.getObjectValue(txb_NotiTitle_5));
    dts_Item.setCellData(1, "NOTI_CONTN", $c.stf.getObjectValue(txa_NotiContn_5));
    dts_Item.setCellData(1, "STRT_DD", $c.stf.getObjectValue(edt_SDate_5_1));
    dts_Item.setCellData(1, "END_DD", $c.stf.getObjectValue(edt_SDate_5_2));
    dts_Item.setCellData(1, "INFO_RND", dts_List_5.getCellData(dts_List_5.getRowPosition(), "INFO_RND"));
    dts_Item.setCellData(1, "ETN_MBR_INFO_TP_CD", scwin.ETN_MBR_INFO_TP_CD);
    trs_Save.Action = "/etn/EtnStatMgt.do?method=saveEtnExchDeclInfo&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + vScrenProcsTpCD;
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_Item)";

    //alert(dts_Item.Text);
    trs_Save.Post();
};
scwin.fn_save = function() {
    if ($c.en.fn_CheckForm()) {
        if (!$c.lce.fn_isProcess(scwin.TR_JOB)) return;
        dts_Item.setCellData(1, "TR_JOB", scwin.TR_JOB);
        dts_Item.setCellData(1, "ETN_MBR_INFO_TP_CD", scwin.ETN_MBR_INFO_TP_CD);
        dts_Item.setCellData(1, "EMP_NO", js_id);
        scwin.fn_trs();
    }
};
scwin.fn_delete = function() {
    scwin.TR_JOB = "D";
    if ($c.en.fn_CheckForm()) {
        if (!$c.lce.fn_isProcess(scwin.TR_JOB)) return;
        dts_Item.setCellData(1, "TR_JOB", scwin.TR_JOB);
        dts_Item.setCellData(1, "ETN_MBR_INFO_TP_CD", scwin.ETN_MBR_INFO_TP_CD);
        scwin.fn_trs();
    }
};
scwin.fn_SendMail = function() {
    if ($c.en.fn_CheckForm()) {
        var res = window.confirm("[메일]을 전송하시겠습니까?");
        if (res) {
            var NotiTitle = $c.stf.getObjectValue(txb_NotiTitle_5);
            var NotiContn = $c.stf.getObjectValue(txa_NotiContn_5);
            trs_MailList.Action = $c.lce.fn_encodeNSession("/etn/EtnStatMgt.do?method=sendEmailData");
            trs_MailList.KeyName = "toinb_dataid4";
            trs_MailList.KeyValue = "JSP(I:pInput=dts_MailList)";
            trs_MailList.Parameters = "NotiTitle=" + NotiTitle + ",NotiContn=" + NotiContn + ",SCREN_ID=" + scwin.vScrenID + ",SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
            trs_MailList.Post();
        }
    }
};
scwin.gform_onload = function() {
    scwin.fn_SetDataHeader();
    scwin.fn_Enable_BtnSend(false);
    scwin.fn_list_sync();
};
scwin.dts_List_5_OnLoadCompleted = function(rowcount) {
    $c.cm.CloseWin(rowcount, grd_List_5);
};
scwin.dts_List_5_OnLoadError = function() {
    $c.stf.alert_error(dts_List_5);
};
scwin.trs_Save_OnSuccess = function() {
    $c.lce.fn_alertMsg('S');
    scwin.fn_list_sync();
    scwin.fn_Disable_Item();
    scwin.fn_Enable_BtnSend(false);
};
scwin.trs_Save_OnFail = function() {
    $c.win.alert("Error Code : " + trs_Save.ErrorCode + "\n" + "Error Message : " + trs_Save.ErrorMsg + "\n");
    $c.lce.fn_alertMsg('F');
    $c.stf.alert_error(trs_Save);
};
scwin.btn_SDate_5_2_onclick = function() {
    popUpCalendar2(edt_SDate_5_2);
};
scwin.btn_SDate_5_1_onclick = function() {
    popUpCalendar2(edt_SDate_5_1);
};
scwin.grd_List_5_OnClick = function(row, colid) {
    scwin.fn_SetValue(row);
    scwin.fn_Enable_BtnSend(true);
};
scwin.btn_Close_5_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.btn_Delete_5_onclick = function() {
    scwin.fn_delete();
};
scwin.btn_Modify5_onclick = function() {
    scwin.fn_save();
};
scwin.btn_New_5_onclick = function() {
    scwin.TR_JOB = "I";
    scwin.fn_Enable_Item();
    scwin.fn_Enable_BtnSend(false);
};
scwin.btn_Send_Mail_onclick = function() {
    scwin.fn_SendMail();
};
scwin.trs_MailList_OnFail = function() {
    var ErrorCount = trs_MailList.SrvErrCount("ACTION");
    if (ErrorCount > 0) {
        $c.win.alert("전송 실패");
        $c.stf.alert_error(trs_MailList);
    } else {
        // 이건 성공임.
        $c.win.alert("전송 성공");
    }
};
scwin.trs_MailList_OnSuccess = function() {
    $c.win.alert("전송 성공");
};
scwin.dts_MailList_OnLoadCompleted = function(rowcount) {
    //alert('dts_MailList.OnLoadCompleted('+rowcount+')'+dts_MailList.NameString(1, "EMAIL") );

};
